document.addEventListener('DOMContentLoaded',function(){const toggleButton=document.querySelector('.menu-toggle');const navMenu=document.getElementById('main-navigation');if(toggleButton&&navMenu){const setMenuState=(isOpen)=>{navMenu.classList.toggle('active',isOpen);navMenu.setAttribute('aria-hidden',(!isOpen).toString());toggleButton.setAttribute('aria-expanded',isOpen.toString());};setMenuState(false);toggleButton.addEventListener('click',()=>{const isOpen=navMenu.classList.contains('active');setMenuState(!isOpen);});navMenu.querySelectorAll('a').forEach((link)=>{link.addEventListener('click',()=>setMenuState(false));});}
const counterElements=document.querySelectorAll('.stat-number');const animateCounter=(element)=>{const finalCount=parseInt(element.getAttribute('data-count'),10);let currentCount=0;const duration=2000;const startTime=performance.now();const plusSign=element.querySelector('.plus-sign');const updateCount=(timestamp)=>{const elapsedTime=timestamp-startTime;const progress=Math.min(elapsedTime/duration,1);currentCount=Math.floor(progress*finalCount);let displayValue=currentCount.toLocaleString();if(plusSign){element.innerHTML=displayValue+'<span class="plus-sign">+</span>';}else{element.textContent=displayValue;}
if(progress<1){requestAnimationFrame(updateCount);}else{if(plusSign){element.innerHTML=finalCount.toLocaleString()+'<span class="plus-sign">+</span>';}else{element.textContent=finalCount.toLocaleString();}}};element.setAttribute('data-animated','true');requestAnimationFrame(updateCount);};const observerOptions={root:null,rootMargin:'0px',threshold:0.8};const counterObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting&&!entry.target.hasAttribute('data-animated')){animateCounter(entry.target);observer.unobserve(entry.target);}});},observerOptions);counterElements.forEach(counter=>{counterObserver.observe(counter);});const swiperContainers=document.querySelectorAll('.blog-slider-container');if(swiperContainers.length){swiperContainers.forEach((swiperContainer)=>{if(!swiperContainer.classList.contains('swiper')){swiperContainer.classList.add('swiper');}
const paginationEl=swiperContainer.querySelector('.swiper-pagination');const nextEl=swiperContainer.querySelector('.swiper-button-next');const prevEl=swiperContainer.querySelector('.swiper-button-prev');new Swiper(swiperContainer,{loop:true,spaceBetween:30,slidesPerView:1,autoplay:{delay:3000,disableOnInteraction:false,},pagination:paginationEl?{el:paginationEl,clickable:true,}:undefined,navigation:nextEl&&prevEl?{nextEl,prevEl,}:undefined,breakpoints:{768:{slidesPerView:2,spaceBetween:30,},1200:{slidesPerView:3,spaceBetween:30,}}});});}
const portfolioLinks=document.querySelectorAll('.portfolio-popup');const lightbox=document.getElementById('portfolio-lightbox');const lightboxImage=lightbox?lightbox.querySelector('.portfolio-lightbox-image'):null;const lightboxClose=lightbox?lightbox.querySelector('.portfolio-lightbox-close'):null;const closeLightbox=()=>{if(!lightbox||!lightboxImage){return;}
lightbox.classList.remove('is-open');lightbox.setAttribute('aria-hidden','true');lightbox.hidden=true;if(lightboxClose){lightboxClose.setAttribute('tabindex','-1');}
lightboxImage.src='';lightboxImage.alt='';document.body.classList.remove('lightbox-open');};const openLightbox=(imageSrc,imageAlt)=>{if(!lightbox||!lightboxImage){return;}
lightboxImage.src=imageSrc;lightboxImage.alt=imageAlt;lightbox.hidden=false;lightbox.classList.add('is-open');lightbox.setAttribute('aria-hidden','false');if(lightboxClose){lightboxClose.removeAttribute('tabindex');}
document.body.classList.add('lightbox-open');};if(portfolioLinks.length&&lightbox&&lightboxImage&&lightboxClose){portfolioLinks.forEach(link=>{link.addEventListener('click',event=>{event.preventDefault();const image=link.querySelector('img');const imageSrc=link.getAttribute('href')||(image?image.src:'');const imageAlt=image?image.alt:'Portfolio image';if(imageSrc){openLightbox(imageSrc,imageAlt);}});});lightboxClose.addEventListener('click',closeLightbox);lightbox.addEventListener('click',event=>{if(event.target===lightbox){closeLightbox();}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&lightbox.classList.contains('is-open')){closeLightbox();}});}
const blogToggleButton=document.querySelector('[data-blog-toggle]');const latestGrid=document.querySelector('[data-latest-grid]');const blogFilterButtons=document.querySelectorAll('[data-blog-filter]');if(latestGrid){const latestCards=Array.from(latestGrid.querySelectorAll('.blog-card'));const getInitialShowCount=()=>{return window.innerWidth<=768?4:6;};const updateVisibility=()=>{const isCollapsed=latestGrid.classList.contains('is-collapsed');const initialShowCount=getInitialShowCount();const activeFilterBtn=document.querySelector('[data-blog-filter].is-active');const activeCategory=activeFilterBtn?activeFilterBtn.dataset.blogFilter:'all';let visibleCount=0;latestCards.forEach(card=>{const cardCategory=card.dataset.category||'';const matchesFilter=activeCategory==='all'||cardCategory===activeCategory;if(matchesFilter){if(isCollapsed&&visibleCount>=initialShowCount){card.classList.add('is-hidden');}else{card.classList.remove('is-hidden');visibleCount++;}}else{card.classList.add('is-hidden');}});if(blogToggleButton){if(activeCategory!=='all'){blogToggleButton.style.display='none';}else{blogToggleButton.style.display='inline-block';blogToggleButton.textContent=isCollapsed?'View all blogs':'Show fewer blogs';blogToggleButton.setAttribute('aria-expanded',(!isCollapsed).toString());}}};latestGrid.classList.add('is-collapsed');updateVisibility();if(blogToggleButton){blogToggleButton.addEventListener('click',()=>{latestGrid.classList.toggle('is-collapsed');updateVisibility();});}
window.addEventListener('resize',updateVisibility);blogFilterButtons.forEach(button=>{button.addEventListener('click',()=>{blogFilterButtons.forEach(item=>item.classList.remove('is-active'));button.classList.add('is-active');updateVisibility();});});}
const archiveGrid=document.querySelector('.blog-archive-grid');const loadMoreBtn=document.getElementById('loadMoreBtn');if(archiveGrid&&loadMoreBtn){const archiveCards=Array.from(archiveGrid.querySelectorAll('.blog-card'));const ARCHIVE_SHOW_COUNT=3;let hiddenCardsExist=false;archiveCards.forEach((card,index)=>{if(index>=ARCHIVE_SHOW_COUNT){card.classList.add('is-hidden');hiddenCardsExist=true;}});if(!hiddenCardsExist){loadMoreBtn.style.display='none';}
loadMoreBtn.addEventListener('click',()=>{archiveCards.forEach(card=>card.classList.remove('is-hidden'));loadMoreBtn.style.display='none';});}
const backToTopButton=document.querySelector('.back-to-top');if(backToTopButton){const toggleBackToTop=()=>{if(window.scrollY>400){backToTopButton.classList.add('is-visible');}else{backToTopButton.classList.remove('is-visible');}};toggleBackToTop();window.addEventListener('scroll',toggleBackToTop,{passive:true});backToTopButton.addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});});}
const siteHeader=document.querySelector('.site-header');if(siteHeader){const handleScroll=()=>{if(window.scrollY>50){siteHeader.classList.add('scrolled');}else{siteHeader.classList.remove('scrolled');}};window.addEventListener('scroll',handleScroll,{passive:true});handleScroll();}
const interactionButtons=document.querySelectorAll('.interaction-btn');if(interactionButtons.length){const getPostSlug=()=>{const path=window.location.pathname;return path.split('/').pop().replace('.html','');};const postSlug=getPostSlug();interactionButtons.forEach(btn=>{const label=btn.getAttribute('aria-label');if(label==='Like this post'){const storageKey=`blog_like_${postSlug}`;const isLiked=localStorage.getItem(storageKey)==='true';if(isLiked){btn.classList.add('active');btn.querySelector('i').classList.replace('far','fas');}
btn.addEventListener('click',()=>{const currentlyLiked=btn.classList.contains('active');if(currentlyLiked){btn.classList.remove('active');btn.querySelector('i').classList.replace('fas','far');localStorage.removeItem(storageKey);}else{btn.classList.add('active');btn.querySelector('i').classList.replace('far','fas');localStorage.setItem(storageKey,'true');btn.style.transform='scale(1.2)';setTimeout(()=>btn.style.transform='',200);}});}
else if(label==='Bookmark this post'){const storageKey=`blog_bookmark_${postSlug}`;const isBookmarked=localStorage.getItem(storageKey)==='true';if(isBookmarked){btn.classList.add('active');btn.querySelector('i').classList.replace('far','fas');}
btn.addEventListener('click',()=>{const currentlyBookmarked=btn.classList.contains('active');if(currentlyBookmarked){btn.classList.remove('active');btn.querySelector('i').classList.replace('fas','far');localStorage.removeItem(storageKey);}else{btn.classList.add('active');btn.querySelector('i').classList.replace('far','fas');localStorage.setItem(storageKey,'true');}});}
else if(label==='Copy Link'){btn.addEventListener('click',()=>{navigator.clipboard.writeText(window.location.href).then(()=>{const originalIcon=btn.innerHTML;btn.innerHTML='<i class="fas fa-check"></i>';btn.classList.add('active');setTimeout(()=>{btn.innerHTML=originalIcon;btn.classList.remove('active');},2000);}).catch(err=>{console.error('Failed to copy: ',err);});});}
else if(label==='Share on Twitter'){btn.addEventListener('click',(e)=>{e.preventDefault();const url=encodeURIComponent(window.location.href);const text=encodeURIComponent(document.title);window.open(`https://twitter.com/intent/tweet?text=${text}&url=${url}`,'_blank','width=600,height=400');});}
else if(label==='Share on LinkedIn'){btn.addEventListener('click',(e)=>{e.preventDefault();const url=encodeURIComponent(window.location.href);window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${url}`,'_blank','width=600,height=400');});}});}
const testimonialsSlider=document.getElementById('testimonialsSlider');const sliderPrevBtn=document.getElementById('sliderPrev');const sliderNextBtn=document.getElementById('sliderNext');const sliderDots=document.querySelectorAll('#sliderDots .dot');if(testimonialsSlider&&sliderPrevBtn&&sliderNextBtn){const getSlideWidth=()=>{const slide=testimonialsSlider.querySelector('.testimonial-slide');return slide?slide.getBoundingClientRect().width:testimonialsSlider.offsetWidth;};const updateDots=()=>{const slideWidth=getSlideWidth();const scrollPosition=testimonialsSlider.scrollLeft;const activeIndex=Math.round(scrollPosition/slideWidth);sliderDots.forEach((dot,index)=>{dot.classList.toggle('active',index===activeIndex);});};let scrollTimeout;testimonialsSlider.addEventListener('scroll',()=>{clearTimeout(scrollTimeout);scrollTimeout=setTimeout(updateDots,100);},{passive:true});sliderPrevBtn.addEventListener('click',()=>{const slideWidth=getSlideWidth();testimonialsSlider.scrollBy({left:-slideWidth,behavior:'smooth'});});sliderNextBtn.addEventListener('click',()=>{const slideWidth=getSlideWidth();testimonialsSlider.scrollBy({left:slideWidth,behavior:'smooth'});});sliderDots.forEach((dot,index)=>{dot.addEventListener('click',()=>{const slideWidth=getSlideWidth();testimonialsSlider.scrollTo({left:index*slideWidth,behavior:'smooth'});sliderDots.forEach(d=>d.classList.remove('active'));dot.classList.add('active');});});testimonialsSlider.addEventListener('keydown',(e)=>{if(e.key==='ArrowLeft'){e.preventDefault();sliderPrevBtn.click();}else if(e.key==='ArrowRight'){e.preventDefault();sliderNextBtn.click();}});setTimeout(()=>{const revealTestimonials=testimonialsSlider.closest('.reveal');if(revealTestimonials){revealTestimonials.classList.add('is-visible');}},300);}});